import React from 'react';
import { Helmet } from 'react-helmet-async';

export default function Seo({title, description, path='/', type='website', schema}) {
  const canonical = `https://beyond31.online${path}`;
  const fullTitle = title ? `${title} — Beyond31` : 'Beyond31 — Creative technology portfolio';
  return <Helmet>
    <html lang="fr" />
    <title>{fullTitle}</title>
    <meta name="description" content={description} />
    <link rel="canonical" href={canonical} />
    <meta property="og:type" content={type} />
    <meta property="og:title" content={fullTitle} />
    <meta property="og:description" content={description} />
    <meta property="og:url" content={canonical} />
    <meta property="og:site_name" content="Beyond31" />
    <meta name="twitter:card" content="summary_large_image" />
    <meta name="twitter:title" content={fullTitle} />
    <meta name="twitter:description" content={description} />
    {schema && <script type="application/ld+json">{JSON.stringify(schema)}</script>}
  </Helmet>;
}
